NODE_H = 46

# Assign x positions per lane based on order
lane_nodes = {k: [] for k in LANE_Y}
for n in nodes_data:
    lane_nodes[n['lane']].append(n)

for lane in lane_nodes:
    lane_nodes[lane].sort(key=lambda x: x['order'])

