import json, textwrap

with open('/app/benchmark/source_data.json') as f:
    data = json.load(f)

nodes_data = data['pipeline_nodes']['data']
edges_data = data['pipeline_edges']['data']
hpa_data = data['hpa_policies']['data']

LANE_Y = {
    'dev': 100,
    'staging': 280,
    'canary': 460,
    'production': 640,
    'global': 830,
}
LANE_COLORS = {
    'dev': '#3b82f6',
    'staging': '#8b5cf6',
    'canary': '#f59e0b',
    'production': '#10b981',
    'global': '#64748b',
}
LANE_LABELS = {
    'dev': 'Dev Namespace',
    'staging': 'Staging Namespace',
    'canary': 'Canary Namespace',
    'production': 'Production Namespace',
    'global': 'Global Actions',
}
NODE_W = 118
NODE_H = 46

node_pos = {}
for n in nodes_data:
    nid = n['id']
    lane = n['lane']
    typ = n['type']
    lbl = n['label']
    node_pos[nid] = {'lane': lane, 'type': typ, 'label': lbl}

# Hardcoded x positions based on analysis
pos_map = {
    'src-commit': 200, 'ci-build': 340, 'docker-push': 480, 'dev-deploy': 620,
    'dev-smoke': 760, 'dev-hpa-check': 900, 'dev-gate': 1040, 'rollback-dev': 1040,
    'staging-deploy': 200, 'staging-integration': 340, 'staging-hpa-check': 480,
    'staging-perf': 620, 'staging-gate': 760, 'rollback-staging': 760,
    'canary-deploy': 200, 'canary-observe': 340, 'canary-hpa-check': 480,
    'canary-ramp-25': 620, 'canary-observe-2': 760, 'canary-ramp-50': 900,
    'canary-gate': 1040, 'rollback-canary': 1040,
    'prod-blue-green-prep': 200, 'prod-deploy-green': 340, 'prod-green-healthcheck': 480,
    'prod-hpa-check': 620, 'prod-bg-switch-gate': 760, 'prod-switch-traffic': 900,
    'prod-verify': 1040, 'prod-finalize': 1180, 'pipeline-complete': 1320, 'rollback-prod': 760,
    'hpa-scale-up': 500, 'hpa-scale-down': 660, 'alert-oncall': 1400,
}
for nid, x in pos_map.items():
    node_pos[nid]['x'] = x
    if node_pos[nid]['type'] == 'rollback':
        node_pos[nid]['y'] = LANE_Y[node_pos[nid]['lane']] + 65
    elif nid == 'alert-oncall':
        node_pos[nid]['y'] = 710
    else:
        node_pos[nid]['y'] = LANE_Y[node_pos[nid]['lane']]

SVG_W = 1600
SVG_H = 950

node_js = []
for nid, pos in node_pos.items():
    node_js.append({
        'id': nid, 'x': pos['x'], 'y': pos['y'],
        'lane': pos['lane'], 'type': pos['type'], 'label': pos['label']
    })

edge_js = []
for e in edges_data:
    edge_js.append({'from': e['from'], 'to': e['to'], 'type': e['type'], 'label': e.get('label', '')})

hpa_envs = [h['environment'] for h in hpa_data]
hpa_cpu = [h['cpu_target_pct'] for h in hpa_data]
hpa_mem = [h['mem_target_pct'] for h in hpa_data]

def node_type_style(t):
    if t == 'action':
        return 'stroke:var(--accent);fill:rgba(59,130,246,0.10)'
    elif t == 'check':
        return 'stroke:#22c55e;fill:rgba(34,197,94,0.10)'
    elif t == 'decision':
        return 'stroke:var(--warning);fill:rgba(245,158,11,0.12)'
    elif t == 'hpa_decision':
        return 'stroke:var(--accent-secondary);fill:rgba(139,92,246,0.12)'
    elif t == 'rollback':
        return 'stroke:var(--negative);fill:rgba(244,63,94,0.12)'
    elif t == 'hpa_action':
        return 'stroke:#a855f7;fill:rgba(168,85,247,0.12)'
    elif t == 'terminal':
        return 'stroke:var(--positive);fill:rgba(16,185,129,0.15)'
    else:
        return 'stroke:var(--border);fill:var(--surface)'

def node_text_color(t):
    if t == 'rollback':
        return 'var(--negative)'
    return 'var(--text)'

# Build SVG elements
svg_elements = []

# Arrow markers
markers = [
    ('arrow-forward', 'var(--positive)'),
    ('arrow-rollback', 'var(--negative)'),
    ('arrow-bluegreen', 'var(--accent)'),
