svg_elements.append(f'<rect x="10" y="{y-50}" width="{SVG_W-20}" height="90" class="lane-bg" fill="{c}" fill-opacity="0.04" stroke="{c}" stroke-opacity="0.15" stroke-width="1" rx="8"/>')
