    x1 = node_pos[src]['x']
    y1 = node_pos[src]['y']
    x2 = node_pos[tgt]['x']
    y2 = node_pos[tgt]['y']

    # Arrowhead gap
    dx = x2 - x1
    dy = y2 - y1
    dist = max(1, (dx*dx + dy*dy)**0.5)
    gap = NODE_W / 2 + 6
    tx = x2 - dx / dist * gap
    ty = y2 - dy / dist * gap

    if etype == 'forward':
        stroke = 'var(--positive)'
        marker = 'url(#arrow-forward)'
        dash = ''
        width = 1.5
        opacity = 0.7
    elif etype == 'rollback':
        stroke = 'var(--negative)'
        marker = 'url(#arrow-rollback)'
        dash = '4,3'
        width = 2
        opacity = 0.9
    elif etype == 'blue_green':
        stroke = 'var(--accent)'
        marker = 'url(#arrow-bluegreen)'
        dash = ''
        width = 2
        opacity = 0.85
    elif etype == 'hpa_branch':
        stroke = 'var(--warning)'
        marker = 'url(#arrow-hpa)'
        dash = '3,2'
        width = 1.5
        opacity = 0.8
    else:
        stroke = '#888'
        marker = ''
        dash = ''
        width = 1
        opacity = 0.5

    # Curved path for cross-lane or global
    if node_pos[src]['lane'] != node_pos[tgt]['lane'] or node_pos[tgt]['lane'] == 'global':
        midx = (x1 + tx) / 2
        midy = (y1 + ty) / 2
        path = f'M{x1},{y1} C{midx},{y1} {midx},{ty} {tx},{ty}'
    else:
        if y1 == y2:
            path = f'M{x1+NODE_W/2},{y1} L{tx},{ty}'
        else:
            path = f'M{x1},{y1} Q{x1},{(y1+ty)/2} {tx},{ty}'

    svg_elements.append(f'<path d="{path}" class="edge-path" stroke="{stroke}" stroke-width="{width}" stroke-dasharray="{dash}" opacity="{opacity}" marker-end="{marker}"/>')

    if lbl:
        mx = (x1 + tx) / 2
        my = (y1 + ty) / 2
        # offset label slightly
        my -= 6
        # simple bbox estimate
        bw = len(lbl) * 5.5 + 8
        bh = 14
        svg_elements.append(f'<rect x="{mx-bw/2}" y="{my-bh/2}" width="{bw}" height="{bh}" rx="3" fill="var(--bg)" stroke="var(--border)" stroke-width="0.5"/>')
        svg_elements.append(f'<text x="{mx}" y="{my+1}" class="edge-label" fill="var(--text-secondary)">{lbl}</text>')

# Nodes
for n in node_js:
    nid = n['id']
    x = n['x']
    y = n['y']
    typ = n['type']
    lbl = n['label']
    style = node_type_style(typ)
    tc = node_text_color(typ)
    rx = x - NODE_W/2
    ry = y - NODE_H/2
    # special shape for terminal
    if typ == 'terminal':
        svg_elements.append(f'<rect x="{rx}" y="{ry}" width="{NODE_W}" height="{NODE_H}" rx="10" {style} stroke-width="2"/>')
    elif typ == 'decision' or typ == 'hpa_decision':
        svg_elements.append(f'<rect x="{rx}" y="{ry}" width="{NODE_W}" height="{NODE_H}" rx="8" {style} stroke-width="2"/>')
    else:
        svg_elements.append(f'<rect x="{rx}" y="{ry}" width="{NODE_W}" height="{NODE_H}" rx="6" {style} stroke-width="1.5"/>')
    # truncate label if needed
    display_label = lbl if len(lbl) <= 18 else lbl[:17] + '…'
    svg_elements.append(f'<text x="{x}" y="{y+1}" class="node-text" fill="{tc}">{display_label}</text>')

svg_inner = '\n'.join(svg_elements)

